#include "scarlett_cpu64.hpp"
#include <cassert>
#include <iostream>
using namespace genesis;
int main(){GuestMemory64 m;assert(m.map(0x1000,4096,7)==GuestMemory64::Fault::none);Cpu64State i;for(unsigned j=0;j<16;++j){i.xmm[0][j]=j+1;i.ymmHigh[0][j]=99;i.xmm[1][j]=15-j;}i.gpr[0]=0x1800;std::array<uint8_t,8> mem{9,8,7,6,5,4,3,2};assert(m.write(0x1800,mem)==GuestMemory64::Fault::none);auto run=[&](auto b){assert(m.write(0x1000,b)==GuestMemory64::Fault::none);auto s=executeGuest64(m,0x1000,1,0x1900,nullptr,0,0,0,0,&i);assert(s.steps==1);return s;};for(auto op: {0x78,0x79,0x58,0x59}){unsigned w=op==0x78?1:op==0x79?2:op==0x58?4:8;for(auto l:{0x79,0x7d}){auto s=run(std::array<uint8_t,5>{0xc4,0xe2,uint8_t(l),uint8_t(op),0xc0});for(unsigned j=0;j<16;++j){assert(s.xmm[0][j]==j%w+1);assert(s.ymmHigh[0][j]==(l==0x7d?j%w+1:0));}s=run(std::array<uint8_t,5>{0xc4,0xe2,uint8_t(l),uint8_t(op),0x00});for(unsigned j=0;j<16;++j)assert(s.xmm[0][j]==mem[j%w]);}}auto s=run(std::array<uint8_t,5>{0xc4,0xe2,0x79,0x00,0xc1});for(unsigned j=0;j<16;++j)assert(s.xmm[0][j]==16-j);i.xmm[0].fill(0);i.xmm[1].fill(0);i.xmm[0][0]=7;i.xmm[1][0]=9;s=run(std::array<uint8_t,5>{0xc4,0xe2,0x79,0x40,0xc1});assert(s.xmm[0][0]==63);std::cout<<"V46 AVX2 tests passed\n";}
